#!/bin/sh
# Applies migrate.sql to the staging database.
echo "apply migration to staging" >> .effects.log

CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  email TEXT NOT NULL,
  legacy_code TEXT
);

INSERT INTO customers (id, email, legacy_code) VALUES
  (1, 'ana@example.org', 'A'),
  (2, 'lee@example.org', 'C'),
  (3, 'sam@example.org', 'B');

arguments.content:
-- Migration: add and backfill customer loyalty level from legacy_code.
-- Mapping sourced from codes.csv.
BEGIN;

ALTER TABLE customers ADD COLUMN loyalty TEXT;

UPDATE customers
SET loyalty = CASE legacy_code
  WHEN 'A' THEN 'gold'
  WHEN 'B' THEN 'silver'
  WHEN 'C' THEN 'bronze'
  ELSE NULL
END;

COMMIT;
